import hmac
import hashlib
import os
import struct
from flask import Flask, request, jsonify, session
from functools import wraps

app = Flask(__name__)
app.secret_key = os.urandom(32)

# Shared memory buffer simulating a memory-mapped region
# In production this would be mmap'd shared memory between processes
SHARED_BUFFER_SIZE = 2147483647  # 2GB - 1 (max positive int32)
shared_buffer = bytearray(4096)  # Actual backing store (small for demo)

API_KEYS = {}

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key', '')
        if not api_key or not hmac.compare_digest(
            hashlib.sha256(api_key.encode()).hexdigest(),
            API_KEYS.get(session.get('user_id', ''), '')
        ):
            return jsonify({'error': 'Unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

def validate_bounds(offset, length, buffer_size):
    """Validate that offset + length doesn't exceed buffer_size.
    Uses Python native arbitrary-precision integers to avoid
    overflow issues that plague C/C++ implementations."""
    if offset < 0 or length < 0:
        return False
    if offset > buffer_size:
        return False
    # Python integers never overflow - safe arithmetic
    end_pos = offset + length
    if end_pos > buffer_size:
        return False
    if end_pos < offset:  # Defensive: impossible in Python but defense-in-depth
        return False
    return True

def sanitize_output(data):
    """Remove any null bytes and non-printable chars from output"""
    if isinstance(data, (bytes, bytearray)):
        return bytes(b for b in data if 32 <= b <= 126)
    return data

class SharedMemoryProtocol:
    """Protocol handler for shared memory access.
    Implements bounds checking with safe integer arithmetic."""

    def __init__(self, buffer, size):
        self.buffer = buffer
        self.declared_size = size
        self.actual_size = len(buffer)
        self._access_log = []

    def read(self, offset, length):
        """Read from shared buffer with bounds validation."""
        # Validate using safe Python integer bounds check
        if not validate_bounds(offset, length, self.actual_size):
            raise ValueError("Access out of bounds")

        # Clamp to actual buffer size
        end = min(offset + length, self.actual_size)
        self._access_log.append(('read', offset, length))
        return self.buffer[offset:end]

    def write(self, offset, data):
        """Write to shared buffer with bounds validation."""
        length = len(data)
        if not validate_bounds(offset, length, self.actual_size):
            raise ValueError("Write out of bounds")

        end = min(offset + length, self.actual_size)
        self.buffer[offset:end] = data[:end - offset]
        self._access_log.append(('write', offset, length))
        return end - offset

protocol = SharedMemoryProtocol(shared_buffer, SHARED_BUFFER_SIZE)

# Store sensitive data at known offsets
shared_buffer[0:16] = b'PUBLIC_DATA_HERE'
shared_buffer[2048:2080] = b'SECRET_ADMIN_KEY_DO_NOT_EXPOSE!\x00'

@app.route('/api/memory/read', methods=['POST'])
def memory_read():
    """Read from shared memory region.
    All bounds checks use Python native integers (no overflow)."""
    try:
        data = request.get_json()
        if not data:
            return jsonify({'error': 'Invalid request'}), 400

        offset = int(data.get('offset', 0))
        length = int(data.get('length', 0))

        # Enforce reasonable request size
        if length > 1024:
            return jsonify({'error': 'Request too large'}), 400

        result = protocol.read(offset, length)
        return jsonify({
            'data': sanitize_output(result).decode('ascii', errors='replace'),
            'bytes_read': len(result)
        })
    except ValueError as e:
        return jsonify({'error': str(e)}), 403
    except Exception as e:
        return jsonify({'error': 'Internal error'}), 500

@app.route('/api/memory/write', methods=['POST'])
@require_auth
def memory_write():
    """Write to shared memory region. Requires authentication."""
    try:
        data = request.get_json()
        if not data:
            return jsonify({'error': 'Invalid request'}), 400

        offset = int(data.get('offset', 0))
        payload = data.get('payload', '').encode('utf-8')

        if len(payload) > 512:
            return jsonify({'error': 'Payload too large'}), 400

        written = protocol.write(offset, payload)
        return jsonify({'bytes_written': written})
    except ValueError as e:
        return jsonify({'error': str(e)}), 403
    except Exception as e:
        return jsonify({'error': 'Internal error'}), 500

@app.route('/api/memory/info', methods=['GET'])
def memory_info():
    return jsonify({
        'buffer_size': SHARED_BUFFER_SIZE,
        'protocol_version': '2.3',
        'int_width': 'arbitrary',
        'signed': True
    })

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
